boolean isValid(String s){
  Deque<Character> st=new ArrayDeque<>();
  Map<Character,Character> m=Map.of(')','(',']','[','}','{');
  for(char c:s.toCharArray()){
    if(m.containsValue(c)) st.push(c);
    else if(st.isEmpty()||st.pop()!=m.get(c)) return false;
  }
  return st.isEmpty();
}

